use duckdb_neo::{Result, duckdb_entrypoint_c_api_v2, extension::Extension};

#[duckdb_entrypoint_c_api_v2(extension_name = "rusty_quack", api_version = "2.0.0")]
pub fn entrypoint(extension: &Extension) -> Result<()> {
    rusty_quack_core::register(extension)
}

//! `rusty_quack`: a tour of what a Rust extension can register through DuckDB's C API v2.
//!
//! Each module shows one feature of [`duckdb_neo`] and registers it on the
//! [`Extension`] handed to the entrypoint:
//!
//! | Module | Feature | Try it |
//! |---|---|---|
//! | [`scalar`] | scalar function with per-query init state | `SELECT rusty_echo('Jane')` |
//! | [`quack`] | table function with bind data, global and local state | `FROM rusty_quack(['a', 'b'])` |
//! | [`aggregate`] | aggregate function with a full state lifecycle | `SELECT rusty_longest(name) FROM t` |
//! | [`sequence`] | chunked table function with projection and filter pushdown, cardinality and progress | `FROM rusty_sequence(10000) WHERE i < 10` |
//! | [`quack_type`] | custom type and a cast into it | `SELECT 3::QUACK` |

use duckdb_neo::{Result, extension::Extension};

pub mod aggregate;
pub mod quack;
pub mod quack_type;
pub mod scalar;
pub mod sequence;

/// The category every function of this extension is documented under in `duckdb_functions()`.
pub const CATEGORY: &str = "rusty_quack";

/// Register everything the extension provides.
pub fn register(extension: &Extension) -> Result<()> {
    scalar::register(extension)?;
    quack::register(extension)?;
    aggregate::register(extension)?;
    sequence::register(extension)?;
    quack_type::register(extension)?;
    Ok(())
}

//! An aggregate function: `rusty_longest(input)`.
//!
//! [`AggregateCallbacks`] is the full lifecycle DuckDB runs for an aggregate.
//! DuckDB owns the memory for one state per group (for `GROUP BY`) or per
//! partition (for window functions) and calls back in this order.
//!
//! 1. `bind` runs once per call site in a query and validates the arguments.
//! 2. `init` runs once per group and fills a fresh state.
//! 3. `update` runs once per input chunk and folds rows into their group's state.
//! 4. `combine` runs when several threads built partial states for the same
//!    groups and merges them.
//! 5. `finalize` runs once per group and turns a state into a result value.
//!
//! Two callbacks keep their defaults here: `size` reports how many bytes a
//! state needs (the size of `StateItem`), and `destroy` lets you clean up
//! states yourself instead of letting Rust drop them.
//!
//! Because ties go to the lexicographically smaller string, the result does
//! not depend on input order, which the properties tell the optimizer.

use duckdb_neo::{
    DuckDBType, Result,
    aggregate::{AggregateCallbacks, AggregateFunctionBuilder, ReturnTypeHandle, States},
    bind_arguments::BindArguments,
    connection::Context,
    data_chunk::VectorCollection,
    enums::AggregateFunctionProperty,
    extension::Extension,
    signature::{FunctionDocumentationBuilder, FunctionParameter, SignatureBuilder},
    vector::{Unknown, Vector},
};

use crate::CATEGORY;

struct Longest;

/// Replace `state` with `candidate` when it is longer, or equally long and lexicographically smaller.
fn keep_longer(state: &mut Option<String>, candidate: &str) {
    let replace = match state {
        None => true,
        Some(current) => {
            let (candidate_len, current_len) = (candidate.chars().count(), current.chars().count());
            candidate_len > current_len
                || (candidate_len == current_len && candidate < current.as_str())
        }
    };
    if replace {
        *state = Some(candidate.to_owned());
    }
}

impl AggregateCallbacks for Longest {
    /// Whatever `bind` computes once per call site; every later callback receives it.
    type BindData = ();
    /// The per-group accumulator; here the longest string seen so far, `None` until a non-NULL value arrives.
    type StateItem = Option<String>;

    /// Runs once when the query is bound. Typical work:
    /// - Inspect the argument types or constant arguments and reject what the function cannot handle.
    /// - Pick the return type with `result_type` when it depends on the arguments.
    /// - Return as `BindData` whatever every later callback needs, such as parsed options or a lookup table.
    fn bind(
        &self,
        _context: &Context,
        _arguments: BindArguments<'_>,
        _result_type: ReturnTypeHandle<'_>,
    ) -> Result<Self::BindData> {
        Ok(())
    }

    /// Runs once per group to create its empty state. Typical work:
    /// - Return the identity of the aggregation, such as zero counts, `None`, or an empty list.
    ///
    /// It cannot fail, so validation belongs in `bind`.
    fn init(&self, _bind_data: Option<&Self::BindData>) -> Self::StateItem {
        None
    }

    /// Runs once per input chunk. Typical work:
    /// - Read one vector per argument from `data`.
    /// - Skip NULL rows unless the aggregate counts them.
    /// - Fold each row into `states[row]`, the state of the group that row belongs to.
    ///
    /// Several rows of a chunk usually share one state.
    fn update(
        &self,
        _bind_data: Option<&Self::BindData>,
        data: &mut VectorCollection,
        mut states: States<'_, Self::StateItem>,
    ) -> Result<()> {
        let input = data.get_vector_at::<String>(0)?;
        for (row, value) in input.reader()?.iter().enumerate() {
            if let Some(value) = value {
                keep_longer(&mut states[row], value);
            }
        }
        Ok(())
    }

    /// Runs when parallel threads each built a partial state for the same group. Typical work:
    /// - Merge `source[i]` into `target[i]` the way `update` merges a row. Add counts, keep the
    ///   maximum, or append lists.
    ///
    /// The merge must give the same result as if all rows had gone through one `update`.
    fn combine(
        &self,
        _bind_data: Option<&Self::BindData>,
        source: &States<'_, Self::StateItem>,
        mut target: States<'_, Self::StateItem>,
    ) -> Result<()> {
        for index in 0..target.len() {
            if let Some(candidate) = &source[index] {
                keep_longer(&mut target[index], candidate);
            }
        }
        Ok(())
    }

    /// Runs once per group at the end. Typical work:
    /// - Compute the final value from each state, such as a division, a median, or the kept value.
    /// - Write it to row `result_offset + i` of `result`, with `None` for groups that saw no input.
    ///
    /// The offset is non-zero when DuckDB finalizes a batch of groups into the middle of a larger vector.
    fn finalize(
        &self,
        _bind_data: Option<&Self::BindData>,
        states: &[&Self::StateItem],
        result: Vector<'_, Unknown>,
        result_offset: usize,
    ) -> Result<()> {
        let mut result = result.cast::<String>()?;
        let mut writer = result.writer()?;
        for (index, state) in states.iter().enumerate() {
            writer.set(result_offset + index, state.as_deref())?;
        }
        Ok(())
    }
}

pub fn register(extension: &Extension) -> Result<()> {
    AggregateFunctionBuilder::new(
        "rusty_longest",
        SignatureBuilder::new()
            .param(FunctionParameter::new::<String>("input"))
            .return_type(String::logical_type(extension)?)
            .documentation(
                FunctionDocumentationBuilder::new()
                    .description("The longest non-NULL string in the group; ties go to the lexicographically smaller one.")
                    .add_example("Longest name", "SELECT rusty_longest(name) FROM (VALUES ('a'), ('ccc'), ('bb')) t(name)")
                    .add_category(CATEGORY),
            ),
        Longest,
    )
    // Both false: the result is the same for any row order and with or without DISTINCT,
    // so the optimizer may skip sorting and de-duplicating the input.
    .set_property(AggregateFunctionProperty::AggregateOrderDependent(false))
    .set_property(AggregateFunctionProperty::AggregateDistinctDependent(false))
    .register(extension)
}

//! A chunked table function with optimizer hooks: `rusty_sequence(count, step := 1)`.
//!
//! DuckDB calls [`TableFunctionCallbacks::exec`] repeatedly, possibly from
//! several workers at once, until a call produces zero rows. A cursor in the
//! global state hands each call its next slice. On top of that this module
//! opts into:
//!
//! - projection pushdown: `exec` only fills the columns the query uses
//!   ([`ExecColumnInfo`] maps output positions to declared columns);
//! - filter pushdown: `i < constant` is claimed in
//!   [`TableFilterPushdownCallbacks::pushdown_filter`] by inspecting the bound
//!   [`Expression`](duckdb_neo::expression::Expression), and enforced in `exec` so DuckDB drops its own filter;
//! - an exact cardinality and a progress fraction.

use std::sync::{
    Mutex,
    atomic::{AtomicU64, Ordering},
};

use duckdb_neo::{
    DuckDBType, Result,
    bind_arguments::BindArgument,
    connection::Context,
    data_chunk::DataChunkRef,
    error::Error,
    expression::ExpressionType,
    extension::Extension,
    signature::{FunctionDocumentationBuilder, FunctionParameter, SignatureBuilder},
    table_function::{
        BindFunctionHandle, ExecColumnInfo, InitColumnData, PushdownData,
        TableFilterPushdownCallbacks, TableFunctionBuilder, TableFunctionCallbacks,
    },
};

use crate::CATEGORY;

/// Declared column positions, as given to `add_result_column`.
const COLUMN_I: usize = 0;
const COLUMN_LABEL: usize = 1;

/// The registered implementation; it has no fields, so all state lives in bind data and global state.
struct Sequence;

/// What `bind` computes once per call site; every later callback receives it.
struct SequenceBind {
    count: u64,
    step: i64,
    /// An accepted `i < limit` filter; rows at or above it are never emitted.
    limit: Mutex<Option<i64>>,
}

impl SequenceBind {
    /// `bind` checked that the last row's value fits in an `i64`, so no row can overflow here.
    fn value_at(&self, row: u64) -> i64 {
        row as i64 * self.step
    }

    fn passes(&self, value: i64, limit: Option<i64>) -> bool {
        limit.is_none_or(|limit| value < limit)
    }
}

/// Read argument `index` as `T`, treating SQL NULL as `None`.
fn argument<T: duckdb_neo::FromValue>(
    arguments: &[BindArgument],
    index: usize,
) -> Result<Option<T>> {
    match arguments
        .get(index)
        .and_then(|argument| argument.value.as_ref())
    {
        Some(value) => value.get::<T>(),
        None => Ok(None),
    }
}

impl TableFunctionCallbacks for Sequence {
    type BindData = SequenceBind;
    /// The next row to hand out, shared by every worker of the scan.
    type GlobalState = AtomicU64;
    /// Nothing per worker: every call claims its slice from the global cursor.
    type LocalState = ();

    /// Runs once when the query is bound. Typical work:
    /// - Read and validate the constant arguments; reject what the function cannot handle.
    /// - Declare the result columns with `add_result_column`, in the order the column
    ///   constants above use.
    /// - Tell the optimizer what is known up front, such as an exact cardinality.
    fn bind(
        &self,
        context: &Context,
        arguments: Vec<BindArgument>,
        bind_handle: BindFunctionHandle<'_>,
    ) -> Result<Self::BindData> {
        let count = match argument::<i64>(&arguments, 0)? {
            None => 0,
            Some(count) if count < 0 => {
                return Err(Error::invalid_input(
                    "rusty_sequence: count must not be negative",
                ));
            }
            Some(count) => count as u64,
        };
        let step = argument::<i64>(&arguments, 1)?.unwrap_or(1);
        if step == 0 {
            return Err(Error::invalid_input(
                "rusty_sequence: step must not be zero",
            ));
        }
        // Every value is `row * step` with `row < count`, so the last row bounds them all.
        if count > 0
            && (count - 1)
                .checked_mul(step.unsigned_abs())
                .is_none_or(|last| last > i64::MAX as u64)
        {
            return Err(Error::invalid_input(
                "rusty_sequence: count * step does not fit in a BIGINT",
            ));
        }

        bind_handle.add_result_column("i", &i64::logical_type(context)?)?;
        bind_handle.add_result_column("label", &String::logical_type(context)?)?;
        bind_handle.set_cardinality(count as usize, true)?;

        Ok(SequenceBind {
            count,
            step,
            limit: Mutex::new(None),
        })
    }

    /// Runs once per scan. Typical work:
    /// - Create the state every worker shares; here the cursor, an atomic so workers
    ///   can claim slices without a lock.
    /// - Return a thread limit as the second value, or `None` for DuckDB's default.
    fn init_global_state(
        &self,
        _bind_data: &Self::BindData,
        _context: &Context,
        _column_data: InitColumnData<'_>,
    ) -> Result<(Option<Self::GlobalState>, Option<usize>)> {
        Ok((Some(AtomicU64::new(0)), None))
    }

    /// Runs once per worker. This function needs no per-worker state, so it returns `None`.
    fn init_local_state(
        &self,
        _bind_data: &Self::BindData,
        _global_state: Option<&Self::GlobalState>,
        _context: &Context,
        _column_data: InitColumnData<'_>,
    ) -> Result<Option<Self::LocalState>> {
        Ok(None)
    }

    /// Runs whenever DuckDB asks how far the scan is, only when registered with
    /// `with_progress`. Typical work:
    /// - Compare the shared cursor with the total, and return a fraction from `0.0` to `1.0`.
    /// - Return `None` when progress cannot be estimated.
    fn progress(
        &self,
        bind_data: &Self::BindData,
        global_state: Option<&Self::GlobalState>,
        _context: &Context,
    ) -> Result<Option<f64>> {
        let Some(cursor) = global_state else {
            return Ok(None);
        };
        if bind_data.count == 0 {
            return Ok(Some(1.0));
        }
        let done = cursor.load(Ordering::Relaxed).min(bind_data.count);
        Ok(Some(done as f64 / bind_data.count as f64))
    }

    /// Runs until the output chunk stays empty, possibly on several workers at once.
    /// Typical work:
    /// - Claim the next slice of work from the global state.
    /// - Apply the filters accepted in `pushdown_filter`, so no emitted row violates them.
    /// - Fill only the columns in `columns`: with projection pushdown, output position `i`
    ///   maps to declared column `columns.get_column_index(i)`.
    /// - Leave the chunk empty once there is nothing left; an empty chunk ends the scan,
    ///   so a slice that filters down to nothing must not be returned as-is.
    fn exec(
        &self,
        bind_data: &Self::BindData,
        global_state: Option<&Self::GlobalState>,
        _local_state: Option<&mut Self::LocalState>,
        _context: &Context,
        mut output: DataChunkRef<'_>,
        columns: ExecColumnInfo<'_>,
    ) -> Result<()> {
        let cursor =
            global_state.ok_or_else(|| Error::internal("rusty_sequence: missing global state"))?;
        let capacity = output.capacity()? as u64;
        let limit = *bind_data.limit.lock().unwrap();

        // Claim slices until one yields rows, because an empty chunk ends the scan.
        let rows: Vec<u64> = loop {
            let start = cursor.fetch_add(capacity, Ordering::SeqCst);
            if start >= bind_data.count {
                break Vec::new();
            }
            let end = (start + capacity).min(bind_data.count);
            let rows: Vec<u64> = (start..end)
                .filter(|&row| bind_data.passes(bind_data.value_at(row), limit))
                .collect();
            if !rows.is_empty() {
                break rows;
            }
        };

        for position in 0..columns.count()? {
            match columns.get_column_index(position)? {
                COLUMN_I => {
                    let mut vector = output.get_vector_at_mut::<i64>(position)?;
                    vector.set_size(rows.len())?;
                    let mut writer = vector.writer()?;
                    for (index, &row) in rows.iter().enumerate() {
                        writer.set(index, Some(bind_data.value_at(row)))?;
                    }
                }
                COLUMN_LABEL => {
                    let mut vector = output.get_vector_at_mut::<String>(position)?;
                    vector.set_size(rows.len())?;
                    let mut writer = vector.writer()?;
                    for (index, &row) in rows.iter().enumerate() {
                        writer.set(index, Some(&format!("row {}", bind_data.value_at(row))))?;
                    }
                }
                other => {
                    return Err(Error::internal(format!(
                        "rusty_sequence: unknown column {other}"
                    )));
                }
            }
        }
        Ok(())
    }
}

impl TableFilterPushdownCallbacks for Sequence {
    /// Runs once per scan, between `bind` and `init_global_state`, only when registered with
    /// `with_filter_pushdown`. Typical work:
    /// - Walk the filter expressions and inspect their shape (comparison, column reference,
    ///   constant).
    /// - Record the ones the function will enforce in the bind data (hence the `Mutex`),
    ///   and call `accept_pushdown` so DuckDB drops its own copy.
    /// - Leave everything else unclaimed; DuckDB still applies it after the scan.
    ///
    /// Here only `i < constant` is claimed.
    fn pushdown_filter(
        &self,
        bind_data: &Self::BindData,
        _context: &Context,
        pushdown_data: PushdownData<'_>,
    ) -> Result<()> {
        for index in 0..pushdown_data.filter_count()? {
            let filter = pushdown_data.filter(index)?;
            if filter.expression_type()? != ExpressionType::CompareLessThan
                || filter.child_count()? != 2
            {
                continue;
            }
            let (column, constant) = (filter.child(0)?, filter.child(1)?);
            if column.expression_type()? != ExpressionType::BoundColumnRef
                || constant.expression_type()? != ExpressionType::ValueConstant
            {
                continue;
            }
            // The column reference indexes the scan's projected columns.
            if pushdown_data.get_column_index(column.reference_index()?)? != COLUMN_I {
                continue;
            }
            let Some(limit) = constant.get_constant_value()?.get::<i64>()? else {
                continue;
            };
            let mut accepted = bind_data.limit.lock().unwrap();
            *accepted = Some(accepted.map_or(limit, |current| current.min(limit)));
            pushdown_data.accept_pushdown(index)?;
        }
        Ok(())
    }
}

pub fn register(extension: &Extension) -> Result<()> {
    TableFunctionBuilder::new(
        "rusty_sequence",
        SignatureBuilder::new()
            .param(FunctionParameter::new::<i64>("count"))
            .param(FunctionParameter::with_default("step", 1_i64))
            .documentation(
                FunctionDocumentationBuilder::new()
                    .description("count rows of i = 0, step, 2*step, ... with a label; filters on i < constant are pushed into the scan.")
                    .add_example("First ten rows", "SELECT i FROM rusty_sequence(10000) WHERE i < 10")
                    .add_example("With a step", "SELECT * FROM rusty_sequence(3, step := 10)")
                    .add_category(CATEGORY),
            ),
        Sequence,
    )
    .with_projection_pushdown(true)
    .with_filter_pushdown()
    .with_progress()
    .register(extension)
}

use duckdb_neo::{Result, duckdb_entrypoint_c_api_v2, extension::Extension};

#[duckdb_entrypoint_c_api_v2(extension_name = "rusty_quack", api_version = "2.0.0")]
pub fn entrypoint(extension: &Extension) -> Result<()> {
    rusty_quack_core::register(extension)
}

//! A custom type and a cast into it: `3::QUACK`.
//!
//! Two registrations work together:
//!
//! 1. [`CustomType`] registers `QUACK` as a named alias of `VARCHAR`, so it can
//!    be used in `CAST` and column definitions.
//! 2. [`CastFunctionBuilder`] adds the `INTEGER -> QUACK` conversion, with
//!    [`CastFunctionCallbacks::exec`] as the only callback; DuckDB runs it once
//!    per input chunk. [`CastMode`] tells it whether a failing row must raise an
//!    error (`CAST`) or become NULL (`TRY_CAST`).

use duckdb_neo::{
    DuckDBType, Result,
    cast::{CastFunctionBuilder, CastFunctionCallbacks, CastMode},
    connection::Context,
    custom_type::CustomType,
    error::Error,
    extension::Extension,
    vector::Vector,
};

/// The type's name in SQL.
pub const TYPE_NAME: &str = "QUACK";

/// The largest integer the cast accepts.
const MAX_QUACKS: i32 = 10;

/// The registered implementation of the `INTEGER -> QUACK` cast.
struct IntegerToQuack;

impl CastFunctionCallbacks for IntegerToQuack {
    /// The Rust type of the source vector; it fixes the source logical type (`INTEGER`).
    type InputType = i32;
    /// The Rust type of the target vector; `QUACK` is stored as `VARCHAR`, so `String`.
    type OutputType = String;

    /// Runs once per input chunk. Typical work:
    /// - Size the output to the input, then read and write row by row, `None` for NULL.
    /// - On a row that cannot convert, consult `mode`: return an error for `CAST`,
    ///   write `None` for `TRY_CAST`.
    fn exec(
        &self,
        _context: &Context,
        mode: CastMode,
        input: Vector<'_, Self::InputType>,
        mut output: Vector<'_, Self::OutputType>,
    ) -> Result<()> {
        output.set_size(input.len())?;
        let reader = input.reader()?;
        let mut writer = output.writer()?;

        for (row, value) in reader.iter().enumerate() {
            match value {
                None => writer.set(row, None)?,
                Some(&count) if (0..=MAX_QUACKS).contains(&count) => {
                    writer.set(row, Some(&"quack".repeat(count as usize)))?
                }
                Some(count) => match mode {
                    CastMode::Try => writer.set(row, None)?,
                    CastMode::Normal => {
                        return Err(Error::invalid_input(format!(
                            "cannot cast {count} to {TYPE_NAME}: the value must be between 0 and {MAX_QUACKS}"
                        )));
                    }
                },
            }
        }
        Ok(())
    }
}

pub fn register(extension: &Extension) -> Result<()> {
    let base = String::logical_type(extension)?;
    CustomType::new(TYPE_NAME, base.clone()).register(extension)?;

    // The cast targets the aliased type, so `typeof(3::QUACK)` reports QUACK rather than VARCHAR.
    let quack = base.with_alias(extension, TYPE_NAME)?;
    CastFunctionBuilder::new(i32::logical_type(extension)?, quack, IntegerToQuack)
        .register(extension)
}

//! A scalar function: `rusty_echo(input)`.
//!
//! [`ScalarCallbacks`] is the lifecycle DuckDB runs for a scalar function.
//! DuckDB calls back in this order:
//!
//! 1. `bind` (kept at its default here) runs once per call site in a query.
//! 2. `init` runs once per query and worker, before any `exec`, when the
//!    function is registered with `with_init`.
//! 3. `exec` runs once per input chunk and fills the output vector.
//!
//! The documentation builder makes the function discoverable in
//! `duckdb_functions()`.

use duckdb_neo::{
    DuckDBType, Result,
    connection::Context,
    data_chunk::VectorCollection,
    error::Error,
    extension::Extension,
    scalar::{ScalarCallbacks, ScalarFunctionBuilder, ScalarInitCallbacks},
    signature::{FunctionDocumentationBuilder, FunctionParameter, SignatureBuilder},
    vector::{Unknown, Vector},
};

use crate::CATEGORY;

/// Echoes its input twice: `<prefix> <input> <postfix> <input>`.
///
/// The struct itself is the registered implementation, so fields set at
/// registration time (the prefix) are available in every callback.
struct EchoScalar {
    prefix: String,
}

impl ScalarInitCallbacks for EchoScalar {
    /// Runs once per query and worker, before the first `exec`. Typical work:
    /// - Build state that is expensive to create and reusable across chunks, such as
    ///   a compiled regex, a lookup table, or a buffer.
    /// - Read settings from `context` that stay fixed for the query.
    ///
    /// The state is handed to every `exec` as `init_data`; here it is the postfix.
    fn init(
        &self,
        _bind_data: Option<&Self::BindData>,
        _context: &Context,
    ) -> Result<Self::InitData> {
        Ok("🦀".into())
    }
}

impl ScalarCallbacks for EchoScalar {
    /// Whatever `bind` computes once per call site; this function keeps the default `bind`, so nothing.
    type BindData = ();
    /// The per-query, per-worker state created by `init`; here the postfix.
    type InitData = String;

    /// Runs once per input chunk. Typical work:
    /// - Narrow `output` to the declared return type with `cast`.
    /// - Size the output to the input row count.
    /// - Read one vector per argument from `vectors`, and write one result per row,
    ///   `None` for NULL.
    ///
    /// `exec` may run on several workers at once, so it must not keep state in `self`.
    fn exec(
        &self,
        _bind_data: Option<&Self::BindData>,
        init_data: Option<&mut Self::InitData>,
        _context: &Context,
        vectors: &mut VectorCollection,
        output: Vector<'_, Unknown>,
    ) -> Result<()> {
        // The output vector arrives untyped; narrow it to the declared return type.
        let mut output = output.cast::<String>()?;
        output.set_size(vectors.row_count()?)?;

        let prefix = &self.prefix;
        let postfix = init_data.ok_or_else(|| Error::internal("rusty_echo: init state missing"))?;

        let input = vectors.get_vector_at::<String>(0)?;
        let reader = input.reader()?;
        let mut writer = output.writer()?;

        for (row, value) in reader.iter().enumerate() {
            match value {
                Some(value) => {
                    writer.set(row, Some(&format!("{prefix} {value} {postfix} {value}")))?
                }
                None => writer.set(row, None)?,
            }
        }
        Ok(())
    }
}

pub fn register(extension: &Extension) -> Result<()> {
    ScalarFunctionBuilder::new(
        "rusty_echo",
        SignatureBuilder::new()
            .param(FunctionParameter::new::<String>("input"))
            .return_type(String::logical_type(extension)?)
            .documentation(
                FunctionDocumentationBuilder::new()
                    .description("Echo back the input you provided, but with a rusty twist!")
                    .add_example("Echo a name", "SELECT rusty_echo('Jane')")
                    .add_category(CATEGORY),
            ),
        EchoScalar {
            prefix: "🐤".to_string(),
        },
    )
    .with_init()
    .register(extension)
}

//! A table function with state: `rusty_quack(names)`.
//!
//! [`TableFunctionCallbacks`] is the lifecycle DuckDB runs for a table
//! function. DuckDB calls back in this order:
//!
//! 1. `bind` runs once per call site in a query, reads the constant arguments
//!    and declares the result columns.
//! 2. `init_global_state` runs once per scan and creates state shared by all
//!    workers; here it hands out icons.
//! 3. `init_local_state` runs once per worker; here it accumulates the names
//!    a worker has seen.
//! 4. `exec` runs repeatedly, possibly on several workers, until a call leaves
//!    the output chunk empty.
//!
//! This is the template's original example; see [`crate::sequence`] for a
//! function that emits more than one chunk.

use std::sync::{
    Mutex,
    atomic::{AtomicU64, Ordering},
};

use duckdb_neo::{
    DuckDBType, FromValue, Result,
    bind_arguments::BindArgument,
    connection::Context,
    data_chunk::DataChunkRef,
    error::Error,
    extension::Extension,
    signature::{FunctionDocumentationBuilder, FunctionParameter, SignatureBuilder},
    table_function::{
        BindFunctionHandle, ExecColumnInfo, InitColumnData, TableFunctionBuilder,
        TableFunctionCallbacks,
    },
    types::List,
};

use crate::CATEGORY;

/// The registered implementation; the icons are fixed at registration time.
struct EchoTable {
    icons: Vec<String>,
}

impl TableFunctionCallbacks for EchoTable {
    /// Shared by every worker of one scan; here a counter that picks the next icon.
    type GlobalState = AtomicU64;
    /// Owned by one worker; here the names it has emitted so far, joined with `|`.
    type LocalState = String;
    /// Whatever `bind` computes once per call site; here the remaining names.
    /// A `Mutex` because bind data is shared and `exec` pops from it.
    type BindData = Mutex<Vec<Option<String>>>;

    /// Runs once per scan, after `bind`. Typical work:
    /// - Create state every worker shares, such as a cursor or a counter.
    /// - Return a thread limit as the second value, or `None` for DuckDB's default.
    fn init_global_state(
        &self,
        _bind_data: &Self::BindData,
        _context: &Context,
        _column_data: InitColumnData<'_>,
    ) -> Result<(Option<Self::GlobalState>, Option<usize>)> {
        Ok((Some(0.into()), None))
    }

    /// Runs once per worker, after `init_global_state`. Typical work:
    /// - Create per-worker scratch space, such as buffers or a file handle.
    /// - Return `None` when the worker needs nothing of its own.
    fn init_local_state(
        &self,
        _bind_data: &Self::BindData,
        _global_state: Option<&Self::GlobalState>,
        _context: &Context,
        _column_data: InitColumnData<'_>,
    ) -> Result<Option<Self::LocalState>> {
        Ok(Some("".into()))
    }

    /// Runs once when the query is bound. Typical work:
    /// - Declare the result columns with `add_result_column`, in the order `exec` fills them.
    /// - Validate the argument types and constant values, returning an error for what
    ///   the function cannot handle.
    /// - Return as `BindData` whatever the later callbacks need.
    fn bind(
        &self,
        context: &Context,
        arguments: Vec<BindArgument>,
        bind_handle: BindFunctionHandle<'_>,
    ) -> Result<Self::BindData> {
        bind_handle.add_result_column("name", &String::logical_type(context)?)?;
        bind_handle.add_result_column("icon", &String::logical_type(context)?)?;
        bind_handle.add_result_column("concat_name", &String::logical_type(context)?)?;
        bind_handle.add_result_column("total_index", &u64::logical_type(context)?)?;

        let arg = arguments
            .first()
            .ok_or_else(|| Error::invalid_input("rusty_quack expects one argument"))?;

        // A bind callback reports problems by returning an error; a panic would be an internal error instead.
        if arg.logical_type.id()? != <List<String>>::logical_type(context)?.id()? {
            return Err(Error::invalid_input(
                "rusty_quack expects a VARCHAR[] argument",
            ));
        }

        let items = match &arg.value {
            // `List<T>` wraps `Vec<Option<T>>`; a NULL list binds as an empty one.
            Some(value) => <List<String>>::from_value(value)?.unwrap_or_default().0,
            None => Vec::new(),
        };

        Ok(Mutex::new(items))
    }

    /// Runs until the output chunk stays empty. Typical work:
    /// - Take the output vectors, narrow each to its declared type, and size them.
    /// - Fill rows from the bind data and the states, `None` for NULL.
    /// - Leave the chunk empty (or `set_size(0)`) once there is nothing left.
    ///
    /// Here one call emits every remaining name, so the second call ends the scan.
    fn exec(
        &self,
        bind_data: &Self::BindData,
        global_state: Option<&Self::GlobalState>,
        local_state: Option<&mut Self::LocalState>,
        _context: &Context,
        mut output: DataChunkRef<'_>,
        _column_info: ExecColumnInfo<'_>,
    ) -> Result<()> {
        let [name, icon, concat_name, total_index] = output.get_vector_array_mut([0, 1, 2, 3])?;
        let mut name = name.cast::<String>()?;
        let mut icon = icon.cast::<String>()?;
        let mut concat_name = concat_name.cast::<String>()?;
        let mut total_index = total_index.cast::<u64>()?;

        let bind_data_len = bind_data.lock().unwrap().len();

        name.set_size(bind_data_len)?;
        icon.set_size(bind_data_len)?;
        concat_name.set_size(bind_data_len)?;
        total_index.set_size(bind_data_len)?;

        let mut name_writer = name.writer()?;
        let mut icon_writer = icon.writer()?;
        let mut concat_name_writer = concat_name.writer()?;
        let mut total_index_writer = total_index.writer()?;

        let mut index = 0;
        let local_concat = local_state.unwrap();

        while let Some(name) = bind_data.lock().unwrap().pop() {
            match name {
                None => {
                    name_writer.set(index, None)?;
                    icon_writer.set(index, None)?;
                    concat_name_writer.set(index, None)?;
                    total_index_writer.set(index, None)?;
                }
                Some(name) => {
                    let icon_index = global_state.unwrap().fetch_add(1, Ordering::AcqRel);

                    let icon = &self.icons[icon_index as usize % self.icons.len()];

                    local_concat.push_str(&name);
                    local_concat.push('|');

                    name_writer.set(index, Some(&name))?;
                    icon_writer.set(index, Some(icon))?;
                    concat_name_writer.set(index, Some(local_concat))?;
                    total_index_writer.set(index, Some(index as u64))?;
                }
            }
            index += 1;
        }

        Ok(())
    }
}

pub fn register(extension: &Extension) -> Result<()> {
    TableFunctionBuilder::new(
        "rusty_quack",
        SignatureBuilder::new()
            .param(FunctionParameter::new::<List<String>>("names"))
            .documentation(
                FunctionDocumentationBuilder::new()
                    .description("One row per name, last name first, with a rotating icon and the names seen so far.")
                    .add_example("Four names", "SELECT * FROM rusty_quack(['Jane', 'Doe', 'Loves', 'Ducks'])")
                    .add_category(CATEGORY),
            ),
        EchoTable {
            icons: vec!["🐤".into(), "🦀".into(), "🐥".into()],
        },
    )
    .register(extension)
}
